<?php
declare(strict_types=1);
require_once __DIR__ . '/../../app/Database.php';
require_once __DIR__ . '/../../app/Auth.php';
require_once __DIR__ . '/../../app/EventoEstado.php';
exigirAdmin();
$eventoId=(int)($_GET['evento_id']??0);if($eventoId<=0)die('Evento no válido.');
$db=Database::connection();$evento=EventoEstado::exigirEvento($db,$eventoId);$finalizado=EventoEstado::estaFinalizado($evento);
$buscar=trim((string)($_GET['buscar']??''));$porPagina=20;$pagina=max(1,(int)($_GET['pagina']??1));
$where='WHERE ec.evento_id=:evento_id';$params=[':evento_id'=>$eventoId];if($buscar!==''){$where.=" AND (ec.cod LIKE :buscar OR ec.cedula LIKE :buscar OR ec.apellidos_nombres LIKE :buscar OR ec.area LIKE :buscar OR ec.empresa LIKE :buscar)";$params[':buscar']='%'.$buscar.'%';}
$st=$db->prepare("SELECT COUNT(*) FROM evento_colaboradores ec $where");$st->execute($params);$total=(int)$st->fetchColumn();$paginas=max(1,(int)ceil($total/$porPagina));$pagina=min($pagina,$paginas);$offset=($pagina-1)*$porPagina;
$sql="SELECT ec.id,ec.cod,ec.cedula,ec.apellidos_nombres,ec.area,ec.empresa,ec.estado,CASE WHEN EXISTS(SELECT 1 FROM registros r WHERE r.evento_id=ec.evento_id AND r.colaborador_id=ec.id AND r.tipo_registro='ASISTENCIA') THEN 1 ELSE 0 END asistio FROM evento_colaboradores ec $where ORDER BY ec.apellidos_nombres LIMIT :lim OFFSET :off";$st=$db->prepare($sql);foreach($params as $k=>$v)$st->bindValue($k,$v);$st->bindValue(':lim',$porPagina,PDO::PARAM_INT);$st->bindValue(':off',$offset,PDO::PARAM_INT);$st->execute();$rows=$st->fetchAll(PDO::FETCH_ASSOC);
function pageUrl(int $p,int $eventoId,string $buscar):string{return '?'.http_build_query(array_filter(['evento_id'=>$eventoId,'pagina'=>$p,'buscar'=>$buscar],fn($v)=>$v!==''));}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Colaboradores</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial;background:#f4f6f9;color:#1f2937}.nav{background:#1f2937;color:#fff;padding:16px 25px}.wrap{max-width:1400px;margin:25px auto;padding:0 15px}.card{background:#fff;border-radius:10px;padding:20px;margin-bottom:18px;box-shadow:0 2px 8px #0001}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{display:inline-block;padding:10px 15px;border-radius:7px;text-decoration:none;border:0;font-weight:bold;cursor:pointer}.blue{background:#2563eb;color:#fff}.gray{background:#6b7280;color:#fff}.red{background:#dc2626;color:#fff}input{padding:10px;border:1px solid #d1d5db;border-radius:7px;min-width:280px}table{width:100%;border-collapse:collapse;min-width:900px}th,td{padding:10px;border-bottom:1px solid #e5e7eb;text-align:left}.table{overflow:auto}.badge{padding:4px 8px;border-radius:15px;font-size:12px;font-weight:bold}.ok{background:#dcfce7;color:#166534}.wait{background:#f3f4f6;color:#6b7280}.pager{margin-top:18px;display:flex;align-items:center;justify-content:center;gap:5px}.pager a,.pager span{min-width:36px;height:36px;padding:8px 10px;border:1px solid #d1d5db;border-radius:6px;text-decoration:none;color:#374151;text-align:center}.pager a:hover{background:#f3f4f6}.pager .cur{background:#2563eb;color:#fff;border-color:#2563eb;font-weight:bold}.pager .arrow{font-size:18px;font-weight:bold;line-height:18px}.pager .disabled{color:#9ca3af;background:#f8fafc;border-color:#e5e7eb}.pager-info{text-align:center;margin-top:8px;color:#64748b;font-size:13px}@media(max-width:700px){input{width:100%;min-width:0}}</style></head><body><div class="nav"><strong>Songa Event Control — Colaboradores</strong></div><div class="wrap"><div class="card"><div class="actions"><a class="btn gray" href="evento.php?id=<?=$eventoId?>">← Evento</a><?php if(!$finalizado):?><a class="btn blue" href="colaborador_nuevo.php?evento_id=<?=$eventoId?>">＋ Nuevo colaborador</a><?php endif;?><a class="btn blue" href="colaboradores_exportar.php?evento_id=<?=$eventoId?>">⬇ Exportar Excel</a></div><h2><?=htmlspecialchars((string)$evento['nombre'],ENT_QUOTES,'UTF-8')?></h2><?php if($finalizado):?><p><strong>🔒 FINALIZADO:</strong> solo consulta y exportación.</p><?php endif;?><form method="get"><input type="hidden" name="evento_id" value="<?=$eventoId?>"><input name="buscar" value="<?=htmlspecialchars($buscar,ENT_QUOTES,'UTF-8')?>" placeholder="Código, cédula, nombre, área o empresa"> <button class="btn blue">Buscar</button></form></div><div class="card"><p><strong><?=number_format($total)?></strong> colaboradores</p><div class="table"><table><thead><tr><th>Código</th><th>Cédula</th><th>Nombre</th><th>Área</th><th>Empresa</th><th>Estado</th><th>Asistencia</th><?php if(!$finalizado):?><th>Acción</th><?php endif;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars((string)$r['cod'])?></td><td><?=htmlspecialchars((string)$r['cedula'])?></td><td><?=htmlspecialchars((string)$r['apellidos_nombres'])?></td><td><?=htmlspecialchars((string)$r['area'])?></td><td><?=htmlspecialchars((string)$r['empresa'])?></td><td><?=htmlspecialchars((string)$r['estado'])?></td><td><span class="badge <?=$r['asistio']?'ok':'wait'?>"><?=$r['asistio']?'ASISTIÓ':'PENDIENTE'?></span></td><?php if(!$finalizado):?><td><form method="post" action="colaborador_eliminar.php" onsubmit="return confirm('¿Eliminar este colaborador?')"><input type="hidden" name="evento_id" value="<?=$eventoId?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn red">Eliminar</button></form></td><?php endif;?></tr><?php endforeach;if(!$rows):?><tr><td colspan="8">No se encontraron colaboradores.</td></tr><?php endif;?></tbody></table></div><?php if($paginas>1):?><div class="pager"><?php $ventana=2;$inicio=max(1,$pagina-$ventana);$fin=min($paginas,$pagina+$ventana);if($pagina>1):?><a class="arrow" href="<?=pageUrl($pagina-1,$eventoId,$buscar)?>" title="Página anterior">‹</a><?php else:?><span class="arrow disabled">‹</span><?php endif;?><?php if($inicio>1):?><a href="<?=pageUrl(1,$eventoId,$buscar)?>">1</a><?php if($inicio>2):?><span>…</span><?php endif;?><?php endif;?><?php for($p=$inicio;$p<=$fin;$p++):?><?php if($p===$pagina):?><span class="cur"><?=$p?></span><?php else:?><a href="<?=pageUrl($p,$eventoId,$buscar)?>"><?=$p?></a><?php endif;?><?php endfor;?><?php if($fin<$paginas):?><?php if($fin<$paginas-1):?><span>…</span><?php endif;?><a href="<?=pageUrl($paginas,$eventoId,$buscar)?>"><?=$paginas?></a><?php endif;?><?php if($pagina<$paginas):?><a class="arrow" href="<?=pageUrl($pagina+1,$eventoId,$buscar)?>" title="Página siguiente">›</a><?php else:?><span class="arrow disabled">›</span><?php endif;?></div><div class="pager-info">Página <?=$pagina?> de <?=$paginas?> · Mostrando <?=number_format(min($porPagina,$total-($pagina-1)*$porPagina))?> de <?=number_format($total)?> colaboradores</div><?php endif;?></div></div></body></html>